#!/bin/bash
# Some portions generated by Codex. Rebuild the restored pre-experiment source after diagnostics.
set -euo pipefail
cd "$(dirname "$0")/../../.."
exec 8>../.rdf4j-heavy-jvm.lock; flock 8
P=experiments/overlay/memo-hot-split
cmp core/sail/lmdb/src/main/java/org/eclipse/rdf4j/sail/lmdb/evaluation/NativeValueMemo.java "$P/NativeValueMemo.before.java"
bash experiments/overlay/lifetime/mvn.sh -o -pl core/sail/lmdb -Pquick install > maven-build.log 2>&1
cp maven-build.log "$P/restored-install.log"
bash experiments/overlay/lifetime/mvn.sh -o -pl core/sail/lmdb -Dtest=NativeValueMemoTest,NativeMemoPolicyTest,NativeMemoEntryMetadataTest -Drdf4j.lmdb.nativeValueMemo.testProbe=true -DforkCount=1 surefire:test > "$P/restored-tests.log" 2>&1
cat core/sail/lmdb/target/surefire-reports/*Native*Memo*.txt > "$P/restored-reports.txt"
